using System.Collections.Generic;
using Unity.Services.Analytics;
using Unity.Services.Core;
using Unity.Services.Core.Environments;
using UnityEngine;

namespace Astrea;

public class AnalyticsManager : ReferenceSingleton<AnalyticsManager>
{
	private const string areaIndexParameter = "AreaIndex";

	private const string difficultyLevelParameter = "DifficultyLevel";

	private const string battlePackageParameter = "BattlePackage";

	private const string characterParameter = "Character";

	[Header("Assets")]
	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private SaveSystem saveSystem;

	private static bool initialized;

	private bool agreementSave;

	public string AreaIndexParameter => "AreaIndex";

	public string DifficultyLevelParameter => "DifficultyLevel";

	public string BattlePackageParameter => "BattlePackage";

	public string CharacterParameter => "Character";

	protected override void Awake()
	{
		base.Awake();
		if (!initialized)
		{
			initialized = true;
			InitializeAnalytics();
		}
	}

	public async void InitializeAnalytics()
	{
		InitializationOptions initializationOptions = new InitializationOptions();
		initializationOptions.SetEnvironmentName(ReferenceSingleton<AssetsReference>.instance.GameController.IsDemo ? "production-demo" : "production");
		await UnityServices.InitializeAsync(initializationOptions);
		VerifyConsent();
	}

	public void VerifyConsent()
	{
		if (saveSystem.HasAgreementSaveKey() && saveSystem.LoadAgreement())
		{
			ConsentGiven();
		}
	}

	public void RecordEventConvertingOldSDK(string eventName, Dictionary<string, object> eventParams)
	{
		CustomEvent customEvent = new CustomEvent(eventName);
		foreach (string key in eventParams.Keys)
		{
			customEvent.Add(key, eventParams[key]);
		}
		AnalyticsService.Instance.RecordEvent(customEvent);
	}

	public void StarShardsPerAreaAnalytics(bool endOfBattleStateCalling)
	{
		if (saveSystem.HasAgreementSaveKey() && saveSystem.LoadAgreement())
		{
			string eventName = "StarShardsPerArea";
			Dictionary<string, object> eventParams = new Dictionary<string, object>
			{
				{
					"Character",
					ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName
				},
				{
					"AreaIndex",
					mapHandler.CurrentAreaIndex + ((!endOfBattleStateCalling) ? (-1) : 0)
				},
				{
					"StarShardsSpent",
					ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.StarShardsSpentAmount
				},
				{
					"StarShardsEarned",
					ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.StarShardsSpentAmount + ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentGold
				}
			};
			ReferenceSingleton<AnalyticsManager>.Instance.RecordEventConvertingOldSDK(eventName, eventParams);
			AnalyticsService.Instance.Flush();
			Debug.Log("===== Star Shards Per Area Analytics Flushed =====");
		}
	}

	public void BattleEndedAnalytics(bool victory)
	{
		string text = "BattleEnded";
		if (ReferenceSingleton<AssetsReference>.instance.GameController.IsDemo)
		{
			text += "Demo";
		}
		Dictionary<string, object> dictionary = new Dictionary<string, object>
		{
			{ "BattleVictory", victory },
			{
				"Character",
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName
			},
			{
				"BattlePackage",
				GetBattlePackage()
			}
		};
		if (!ReferenceSingleton<AssetsReference>.instance.GameController.IsDemo)
		{
			dictionary.Add("AreaIndex", mapHandler.CurrentAreaIndex);
			dictionary.Add("DifficultyLevel", GetDifficultyLevelString());
			dictionary.Add("Anomaly", GetAnomalyLevel());
			dictionary.Add("Astrea", GetAstreaLevel());
		}
		ReferenceSingleton<AnalyticsManager>.Instance.RecordEventConvertingOldSDK(text, dictionary);
		if (victory)
		{
			AnalyticsService.Instance.Flush();
			Debug.Log("===== Battle Ended Analytics Flushed =====");
		}
	}

	public void PlayerLostHeartOnBattleAnalytics()
	{
		string text = "PlayerLostHeartBattle";
		if (ReferenceSingleton<AssetsReference>.instance.GameController.IsDemo)
		{
			text += "Demo";
		}
		Dictionary<string, object> dictionary = new Dictionary<string, object>
		{
			{
				"Character",
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName
			},
			{
				"BattlePackage",
				GetBattlePackage()
			}
		};
		if (!ReferenceSingleton<AssetsReference>.instance.GameController.IsDemo)
		{
			dictionary.Add("AreaIndex", mapHandler.CurrentAreaIndex);
			dictionary.Add("DifficultyLevel", GetDifficultyLevelString());
			dictionary.Add("Anomaly", GetAnomalyLevel());
			dictionary.Add("Astrea", GetAstreaLevel());
		}
		ReferenceSingleton<AnalyticsManager>.Instance.RecordEventConvertingOldSDK(text, dictionary);
		AnalyticsService.Instance.Flush();
		Debug.Log("===== Player Lost Heart On Battle Analytics Flushed =====");
	}

	public void ConsentGiven()
	{
		AnalyticsService.Instance.StartDataCollection();
		Debug.Log("===== Analytics Service Started Data Collection =====");
	}

	public void ConsentRefused()
	{
		AnalyticsService.Instance.StopDataCollection();
		Debug.Log("===== Analytics Service Stopped Data Collection =====");
	}

	public void EraseSaveButtonPressed(bool beforeDeleteFile)
	{
		if (beforeDeleteFile && saveSystem.HasAgreementSaveKey())
		{
			agreementSave = saveSystem.LoadAgreement();
		}
		else
		{
			saveSystem.SaveAgreement(agreementSave);
		}
	}

	public int GetAnomalyLevel()
	{
		int num = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAnomalyLevel;
		if (num == -1)
		{
			num = 0;
		}
		return num;
	}

	public int GetAstreaLevel()
	{
		int num = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAstreaLevel;
		if (num == -1)
		{
			num = 0;
		}
		return num;
	}

	public string GetDifficultyLevelString()
	{
		return $"An{GetAnomalyLevel()}/As{GetAstreaLevel()}";
	}

	public string GetBattlePackage()
	{
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase)
		{
			return "AstreaSecondPhase";
		}
		if (mapHandler.CurrentCustomEventSetup is MeissaBattleCustomEventSetup)
		{
			return "MeissaBattle";
		}
		if (mapHandler.CurrentCustomEventSetup is CorruptedChestBattleCustomEventSetup)
		{
			return "CorruptedChest";
		}
		return mapHandler.CurrentNodeData.BattlePackage;
	}
}
